    step_commit: str
    base_commit: str
    role: str | None = None
    step_log: str | None = None


@dataclass
class ExperimentStopCondition:
    machine_path: str
    node_name: str


@dataclass
class ExperimentMeta:
    experiment_id: str
    experiment_number: int
    project: str
    quest_type: str
    quest_number: int
    quest_slug: str
    description: str
    start_step: ExperimentStartStep
    stop_condition: ExperimentStopCondition
    worktree_name: str
    branch_name: str
    status: str
    created_at: str
    created_by: str | None = None
    landed_at: str | None = None
    remote_branch: str | None = None
    source_commit: str | None = None


def experiment_dir_name(number: int) -> str:
    return f"{number:04d}"


def experiment_id(
    project: str,
    quest_type: str,
    quest_number: int,
    experiment_number: int,
) -> str:
